const RES = ["SG", "MY", "TH", "ID"], FREE = ["JP", "DE", "US", "KR", "FR"];
const GOAL = 30, END = 138, CW = 40, CH = 24;

function shouldShip(c) { return !RES.includes(c.dest) || c.lic === "ok"; }

function newCrate(g, s) {
  const r = g.rand() < 0.6;
  const dest = r ? g.pick(RES) : g.pick(FREE);
  let lic = "none";
  const roll = g.rand();
  if (roll < 0.45) lic = "ok";
  else if (s.sorted >= 8 && roll < 0.75) lic = "exp";
  s.crates.push({ x: 100, y: -CH, dest, lic, warn: 0 });
}

export default {
  title: "License Check",
  dek: "Ship cleared AI servers, hold unlicensed crates bound for Southeast Asia.",
  width: 240,
  height: 160,
  controls: { layout: "lr", hint: "Left/A: HOLD · Right/D: SHIP" },
  howToPlay: {
    summary: "Sort AI server crates at the dock before they hit the end of the belt.",
    steps: [
      "Crates to SG, MY, TH or ID ship only with a green LIC tag. Hold the rest.",
      "Crates to any other country always ship.",
      "Red EXP tags are expired licenses: they count as no license.",
      "Wrong call or a crate reaching the end = strike. 3 strikes lose; sort 30 to win.",
    ],
    controls: "Left / A = HOLD · Right / D = SHIP",
  },
  init(g) {
    g.state = { crates: [], fly: [], spawnT: 0.3, sorted: 0, strikes: 0, combo: 0, belt: 0, msg: "", msgT: 0, over: false };
    g.score = 0;
  },
  update(g, dt) {
    const s = g.state;
    if (s.over) return;
    const speed = 34 + s.sorted * 1.7;
    s.belt = (s.belt + speed * dt) % 12;
    s.spawnT -= dt;
    const last = s.crates[s.crates.length - 1];
    if (s.spawnT <= 0 && (!last || last.y > 8)) {
      newCrate(g, s);
      s.spawnT = Math.max(0.7, 2.0 - s.sorted * 0.045);
    }
    for (const c of s.crates) c.y += speed * dt;
    const strike = (why) => {
      s.strikes++; s.combo = 0; s.msg = why; s.msgT = 1.2;
      g.sfx("hit"); g.shake(4, 0.2); g.flash("danger", 0.1);
      if (s.strikes >= 3) { s.over = true; g.sfx("lose"); g.lose("Export desk shut down after " + s.sorted + " crates sorted."); }
    };
    const front = s.crates[0];
    if (front && front.y + CH >= END) {
      s.crates.shift();
      g.particles(120, END, "danger", 10);
      strike("Crate stalled at the dock");
      return;
    }
    let dir = 0;
    if (g.pressed("left")) dir = -1;
    if (g.pressed("right")) dir = 1;
    if (dir && front && front.y > -CH / 2) {
      s.crates.shift();
      const ship = dir > 0;
      s.fly.push({ x: front.x, y: front.y, vx: dir * 220, c: front, t: 0.4 });
      if (ship === shouldShip(front)) {
        s.sorted++; s.combo++;
        g.score += 10 + Math.min(s.combo, 10) * 2;
        g.sfx(ship ? "coin" : "click");
        g.particles(dir > 0 ? 220 : 20, front.y + 12, ship ? "ok" : "amber", 8);
        if (s.sorted >= GOAL) { s.over = true; g.sfx("win"); g.win("All " + GOAL + " crates cleared. Score " + g.score + "."); }
      } else {
        strike(ship ? "Unlicensed server shipped" : "Cleared crate held");
      }
    }
    for (const f of s.fly) { f.x += f.vx * dt; f.t -= dt; }
    s.fly = s.fly.filter((f) => f.t > 0);
    if (s.msgT > 0) s.msgT -= dt;
    g.hud("Sorted " + s.sorted + "/" + GOAL + " · " + "♥".repeat(3 - s.strikes));
  },
  draw(g) {
    const s = g.state;
    g.cls("dark");
    // bins
    g.rect(4, 40, 54, 80, "panel", "amber");
    g.txt("HOLD", 31, 72, { color: "amber", size: 9, align: "center", bold: true });
    g.txt("< LEFT", 31, 88, { color: "muted", size: 7, align: "center" });
    g.rect(182, 40, 54, 80, "panel", "ok");
    g.txt("SHIP", 209, 72, { color: "ok", size: 9, align: "center", bold: true });
    g.txt("RIGHT >", 209, 88, { color: "muted", size: 7, align: "center" });
    // belt
    g.rect(94, 0, 52, END, "#1e293b");
    for (let y = -12 + s.belt; y < END; y += 12) g.line(96, y, 144, y, "rule", 1);
    g.rect(90, END, 60, 4, "danger");
    g.txt("LICENSE NEEDED: SG MY TH ID", 120, 150, { color: "tech", size: 7, align: "center" });
    const drawCrate = (c, x, y, hi) => {
      g.rect(x, y, CW, CH, "#7c5a2e", hi ? "white" : "amber");
      g.txt(c.dest, x + CW / 2, y + 3, { color: RES.includes(c.dest) ? "tech" : "white", size: 9, align: "center", bold: true });
      const col = c.lic === "ok" ? "ok" : c.lic === "exp" ? "danger" : "muted";
      const lab = c.lic === "ok" ? "LIC" : c.lic === "exp" ? "EXP" : "---";
      g.rect(x + 8, y + 13, 24, 9, col);
      g.txt(lab, x + CW / 2, y + 14, { color: "black", size: 7, align: "center", bold: true });
    };
    s.crates.forEach((c, i) => {
      const near = c.y + CH > END - 30;
      drawCrate(c, c.x, c.y, i === 0);
      if (i === 0 && near && Math.floor(g.t * 8) % 2) g.rect(c.x - 2, c.y - 2, CW + 4, CH + 4, null, "danger");
    });
    for (const f of s.fly) drawCrate(f.c, f.x, f.y, false);
    if (s.msgT > 0) g.txt(s.msg, 120, 22, { color: "danger", size: 8, align: "center", bold: true });
    g.bar(4, 126, 232, 4, s.sorted / GOAL, "ok", "rule");
  },
};
